+
+    .form-field {
+      margin: 0 0 24px;
+      padding: 24px;
+      border: 1px solid var(--border);
+      border-radius: 18px;
+      background: rgba(13, 17, 23, 0.62);
+    }
+
+    .form-field:last-of-type {
+      margin-bottom: 32px;
+    }
+
+    fieldset {
+      min-width: 0;
+      margin: 0;
+      padding: 0;
+      border: 0;
+    }
+
+    legend {
+      margin-bottom: 8px;
+      color: var(--text);
+      font-size: 1.2rem;
