+      event.preventDefault();
+
+      const selectedCount = new FormData(event.currentTarget).entries().reduce(
+        (count) => count + 1,
+        0
+      );
+
+      document.getElementById("result").textContent =
+        `Submitted. You selected ${selectedCount} answer${selectedCount === 1 ? "" : "s"}.`;
+    });
+  </script>
+</body>
+</html>
*** End Patch
