<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Computer Languages Quiz</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0d1117;
      --panel: #161b22;
      --panel-soft: #21262d;
      --text: #f0f6fc;
      --muted: #9da7b3;
      --accent: #58a6ff;
      --accent-strong: #1f6feb;
      --border: #30363d;
      --focus: #79c0ff;
    }

    * {
      box-sizing: border-box;
    }

    body {
      min-height: 100vh;
      margin: 0;
      font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top left, rgba(88, 166, 255, 0.18), transparent 34rem),
        linear-gradient(135deg, #080b10 0%, var(--bg) 48%, #10151f 100%);
      line-height: 1.5;
    }

    main {
      width: min(920px, calc(100% - 32px));
      margin: 0 auto;
      padding: 56px 0;
    }

    .quiz-card {
      overflow: hidden;
      border: 1px solid var(--border);
      border-radius: 24px;
      background: rgba(22, 27, 34, 0.9);
      box-shadow: 0 24px 80px rgba(0, 0, 0, 0.36);
      backdrop-filter: blur(14px);
    }

    .quiz-header {
      padding: 36px;
      border-bottom: 1px solid var(--border);
      background: linear-gradient(135deg, rgba(88, 166, 255, 0.16), rgba(33, 38, 45, 0.4));
    }

    .eyebrow {
      margin: 0 0 10px;
      color: var(--accent);
      font-size: 0.78rem;
      font-weight: 700;
      letter-spacing: 0.12em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 5vw, 3.4rem);
      line-height: 1.05;
    }

    .intro {
      max-width: 62ch;
      margin: 16px 0 0;
      color: var(--muted);
      font-size: 1.05rem;
    }

    form {
      padding: 32px;
    }

    .form-field {
      margin: 0 0 24px;
      padding: 24px;
      border: 1px solid var(--border);
      border-radius: 18px;
      background: rgba(13, 17, 23, 0.62);
    }

    .form-field:last-of-type {
      margin-bottom: 32px;
    }

    fieldset {
      min-width: 0;
      margin: 0;
      padding: 0;
      border: 0;
    }

    legend {
      margin-bottom: 8px;
      color: var(--text);
      font-size: 1.2rem;
      font-weight: 750;
    }

    .help-text {
      margin: 0 0 18px;
      color: var(--muted);
      font-size: 0.96rem;
    }

    .choices {
      display: grid;
      grid-template-columns: repeat(2, minmax(0, 1fr));
      gap: 12px;
      margin-top: 18px;
    }

    .choice {
      display: flex;
      align-items: flex-start;
      gap: 12px;
      min-height: 56px;
      padding: 14px;
      border: 1px solid var(--border);
      border-radius: 14px;
      background: var(--panel-soft);
      color: var(--text);
      cursor: pointer;
      transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;
    }

    .choice:hover {
      border-color: rgba(88, 166, 255, 0.72);
      background: #26303d;
      transform: translateY(-1px);
    }

    input[type="checkbox"] {
      width: 1.1rem;
      height: 1.1rem;
      margin-top: 0.18rem;
      accent-color: var(--accent);
    }

    input[type="checkbox"]:focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 3px;
    }

    button {
      width: 100%;
      padding: 16px 22px;
      border: 0;
      border-radius: 16px;
      background: linear-gradient(135deg, var(--accent), var(--accent-strong));
      color: #ffffff;
      font: inherit;
      font-weight: 800;
      cursor: pointer;
      box-shadow: 0 14px 34px rgba(31, 111, 235, 0.28);
      transition: filter 160ms ease, transform 160ms ease;
    }

    button:hover {
      filter: brightness(1.08);
      transform: translateY(-1px);
    }

    button:focus-visible {
      outline: 3px solid var(--focus);
      outline-offset: 4px;
    }

    .result {
      margin-top: 18px;
      padding: 16px;
      border: 1px solid rgba(88, 166, 255, 0.42);
      border-radius: 14px;
      background: rgba(88, 166, 255, 0.1);
      color: var(--text);
    }

    .result:empty {
      display: none;
    }

    @media (max-width: 680px) {
      main {
        width: min(100% - 24px, 920px);
        padding: 24px 0;
      }

      .quiz-header,
      form {
        padding: 24px;
      }

      .choices {
        grid-template-columns: 1fr;
      }
    }
  </style>
</head>
<body>
  <main id="root"></main>

  <script>
    const quizQuestions = [
      {
        id: "language-types",
        question: "Which of these are programming languages?",
        helpText: "Select every option that is a computer programming language.",
        choices: ["Python", "JavaScript", "HTML", "Ruby"]
      },
      {
        id: "web-languages",
        question: "Which languages are commonly used to add behavior to web pages?",
        choices: ["JavaScript", "TypeScript", "CSS", "SQL"]
      },
      {
        id: "systems-languages",
        question: "Which languages are often used for systems programming?",
        choices: ["C", "Rust", "Go", "Markdown"]
      }
    ];

    function Question({ id, question, helpText, choices }) {
      const describedBy = helpText ? `${id}-help` : "";
      const choiceMarkup = choices.map((choice, index) => {
        const inputId = `${id}-${index}`;

        return `
          <label class="choice" for="${inputId}">
            <input
              type="checkbox"
              id="${inputId}"
              name="${id}"
              value="${choice}"
              ${describedBy ? `aria-describedby="${describedBy}"` : ""}
            >
            <span>${choice}</span>
          </label>
        `;
      }).join("");

      return `
        <div class="form-field">
          <fieldset>
            <legend>${question}</legend>
            ${helpText ? `<p class="help-text" id="${describedBy}">${helpText}</p>` : ""}
            <div class="choices">
              ${choiceMarkup}
            </div>
          </fieldset>
        </div>
      `;
    }

    function QuizApp({ questions }) {
      const questionsMarkup = questions.map((question) => Question(question)).join("");

      return `
        <article class="quiz-card" aria-labelledby="quiz-title">
          <header class="quiz-header">
            <p class="eyebrow">Multiple answer quiz</p>
            <h1 id="quiz-title">Computer Languages Quiz</h1>
            <p class="intro">
              Choose every answer that fits each question, then submit your selections.
            </p>
          </header>
          <form id="quiz-form">
            ${questionsMarkup}
            <button type="submit">Submit answers</button>
            <div class="result" id="result" role="status" aria-live="polite"></div>
          </form>
        </article>
      `;
    }

    document.getElementById("root").innerHTML = QuizApp({ questions: quizQuestions });

    document.getElementById("quiz-form").addEventListener("submit", (event) => {
      event.preventDefault();

      const selectedCount = new FormData(event.currentTarget).entries().reduce(
        (count) => count + 1,
        0
      );

      document.getElementById("result").textContent =
        `Submitted. You selected ${selectedCount} answer${selectedCount === 1 ? "" : "s"}.`;
    });
  </script>
</body>
</html>
